// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes32 role, address account, address caller) public {
        bytes32 PROPOSER = c.PROPOSER_ROLE();
        bytes32 EXECUTOR = c.EXECUTOR_ROLE();
        bytes32 TIMELOCK = c.TIMELOCK_ADMIN_ROLE();
        vm.assume(role == PROPOSER || role == EXECUTOR || role == TIMELOCK);
        vm.assume(account != caller);
        vm.assume(account != address(this) && caller != address(this));

        // the test contract (deployer) holds TIMELOCK_ADMIN_ROLE and administers all roles
        c.grantRole(role, account);
        assertTrue(c.hasRole(role, account));

        vm.prank(caller);
        bool ok;
        try c.renounceRole(role, account) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: renouncing someone else's role can never succeed, and the account
        // always keeps the role. The mutant strips it without reverting.
        assertTrue(!ok || c.hasRole(role, account));
    }
}
